# utility functions
 
def act(x, rpar):
    # Robust Hill activation. Returns 0 silently if the (EC50, n) combo gives
    # beta <= 1 (invalid Hill regime). The objective function's penalty_B
    # already penalises this upstream, so there is no need to print each
    # occurrence during calibration parameter sweeps.
    w, n, EC50 = rpar
    x = max(x, 0.01)   # lower bound to prevent divide-by-zero

    denom = 2 * EC50**n - 1
    if denom == 0:
        return 0
    beta = (EC50**n - 1) / denom
    if np.isnan(beta) or beta <= 1:
        return 0            # invalid Hill regime; guarded upstream by penalty_B

    with np.errstate(invalid="ignore"):
        K = (beta - 1) ** (1 / n)
    if np.isnan(K) or K == 0:
        return 0

    fact = w * (beta * x**n) / (K**n + x**n)
    return min(fact, w)

def inhib(x, rpar):
    # Robust inverse Hill. Shares the same guards as act().
    w = rpar[0]
    x = max(x, 0.01)
    return w - act(x, rpar)

def OR(x, y): 
	# OR logic gate 
	z = x + y - x*y 
	return z
 
def AND(w, reactList): 
	# AND logic gate, multiplying all of the reactants together 
	if w == 0: 
		z = 0 
	else: 
		p = np.array(reactList).prod() 
		z = p/w**(len(reactList)-1) 
	return z
 
